#include <LiquidCrystal.h>

// Инициализация объекта LCD с указанием пинов
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

void setup() {
  // Указываем размер дисплея (16 символов в 2 строки)
  lcd.begin(16, 2);

  // Очищаем экран
  lcd.clear();

  // Перемещаем курсор в позицию (0, 0) и выводим текст
  lcd.setCursor(0, 0);
  lcd.print("Hello, World!");

  // Перемещаемся на вторую строку и выводим сообщение
  lcd.setCursor(0, 1);
  lcd.print("This is LCD 1608");
}

